//! Utility for detecting and masking sensitive information such as passwords, tokens and
//! private keys. Port of `org.apache.camel.util.SensitiveUtils`.

use crate::string_helper::contains_ignore_case;
use regex::Regex;
use std::collections::HashSet;
use std::sync::OnceLock;

