fn key_set() -> &'static HashSet<&'static str> {
    static SET: OnceLock<HashSet<&'static str>> = OnceLock::new();
    SET.get_or_init(|| SENSITIVE_KEYS.iter().copied().collect())
}

fn pem_private_key() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| {
        Regex::new(
            r"(?si)(-----BEGIN [^-]*PRIVATE KEY-----\s*)(.*?)(\s*-----END [^-]*PRIVATE KEY-----)",
        )
        .unwrap()
    })
}

/// All the sensitive keys in lower-case.
pub fn get_sensitive_keys() -> &'static HashSet<&'static str> {
    key_set()
}

/// All the sensitive keys as a regular expression alternation (each key is escaped), for
/// matching with a case-insensitive [`Regex`].
///
/// This is the Rust equivalent of the Java `getSensitivePattern()`, which used
/// `\Q...\E` quoting.
pub fn get_sensitive_pattern() -> &'static str {
    static PATTERN: OnceLock<String> = OnceLock::new();
    PATTERN.get_or_init(|| {
        SENSITIVE_KEYS
            .iter()
            .map(|k| regex::escape(k))
            .collect::<Vec<_>>()
            .join("|")
    })
}

/// Whether the given configuration property contains a sensitive key (such as password,
/// accesstoken, etc.).
///
/// Only the part after the last `.` is checked, case-insensitively and ignoring dashes, so
/// `foo.bar.access-Key` is sensitive.
///
/// # Arguments
///
/// * `text` - the configuration property
///
/// # Returns
///
/// `true` if sensitive, `false` otherwise.
///
/// # Examples
///
/// ```
/// use camel_util::sensitive_utils::contains_sensitive;
/// assert!(contains_sensitive("app.apiSecret"));
/// assert!(contains_sensitive("sasl-jaas-config"));
/// assert!(!contains_sensitive("foo"));
/// ```
pub fn contains_sensitive(text: &str) -> bool {
    let text = match text.rfind('.') {
        Some(p) => &text[p + 1..],
        None => text,
    };
    let text = text.to_lowercase().replace('-', "");
    key_set().contains(text.as_str())
}

/// Masks passwords embedded in URI userinfo (`scheme://user:password@host`) within free text.
///
/// Complements name-based secret detection: the password has no `password=` key, so key/value
/// maskers never see it.
///
/// The userinfo ends at the last `@` before the path or query, so a password may contain `:`
/// and `@`. A password with an unencoded `/` or `?` is masked up to the `@`, unless it
/// contains something that reads as a query parameter (`?key=` or `&key=`). In free text a URI
/// also ends at a whitespace or a quote. [`crate::uri_support::sanitize_uri`] masks userinfo
/// passwords with the same rule.
///
/// Query-parameter forms such as `?password=secret` are not handled here; use a key/value
/// masker or [`crate::uri_support::sanitize_uri`] for those.
///
/// # Arguments
///
/// * `source` - the text that may contain connection-string style URIs
/// * `mask` - the replacement string for the password (for example `xxxxx`), `None` leaves
///   the source unchanged
///
/// # Returns
///
/// The source with userinfo passwords replaced.
///
/// # Examples
///
/// ```
/// use camel_util::sensitive_utils::mask_user_info_credentials;
/// assert_eq!(
///     "mongodb://user:xxxxx@host:27017/db",
///     mask_user_info_credentials("mongodb://user:pass@host:27017/db", Some("xxxxx"))
/// );
/// ```
pub fn mask_user_info_credentials(source: &str, mask: Option<&str>) -> String {
    match mask {
        Some(mask) if !source.is_empty() => mask_user_info(source, mask, true),
        _ => source.to_string(),
    }
}

/// Masks the userinfo password of every `scheme://user:password@` in the source.
///
/// # Arguments
///
/// * `source` - the source
/// * `mask` - the replacement string for the password
/// * `text` - whether the source is free text, where a whitespace or a quote ends a URI
pub(crate) fn mask_user_info(source: &str, mask: &str, text: bool) -> String {
    let chars: Vec<char> = source.chars().collect();
    let Some(mut idx) = find(&chars, "://", 0) else {
        return source.to_string();
    };
    let mut sb: Option<String> = None;
    let mut copied = 0;
    loop {
        let mut next = idx + 3;
        if idx > 0 && is_scheme_char(chars[idx - 1]) {
            if let Some((pstart, pend)) = password_range(&chars, idx + 3, text) {
                let out = sb.get_or_insert_with(|| String::with_capacity(source.len()));
                out.extend(&chars[copied..pstart]);
                out.push_str(mask);
                copied = pend;
                next = pend;
            }
        }
        match find(&chars, "://", next) {
            Some(i) => idx = i,
            None => break,
        }
    }
    match sb {
        None => source.to_string(),
        Some(mut out) => {
            out.extend(&chars[copied..]);
            out
        }
    }
}

/// Masks the password of a URI path (without the scheme) that starts with `user:password@`.
///
/// # Arguments
///
/// * `path` - the path
/// * `mask` - the replacement string for the password
pub(crate) fn mask_path_user_info(path: &str, mask: &str) -> String {
    let chars: Vec<char> = path.chars().collect();
    match password_range(&chars, 0, false) {
        None => path.to_string(),
        Some((start, end)) => {
            let mut out: String = chars[..start].iter().collect();
            out.push_str(mask);
            out.extend(&chars[end..]);
            out
        }
    }
}

fn find(chars: &[char], needle: &str, from: usize) -> Option<usize> {
    let n: Vec<char> = needle.chars().collect();
    if from > chars.len() {
        return None;
    }
    (from..=chars.len().saturating_sub(n.len())).find(|&i| chars[i..].starts_with(&n))
}

fn starts_with_at(chars: &[char], needle: &str, at: usize) -> bool {
    let n: Vec<char> = needle.chars().collect();
    at <= chars.len() && chars[at..].starts_with(&n)
}

/// The start and end of the password in the userinfo of the authority that begins at
/// `start`, or `None` if there is none.
fn password_range(source: &[char], start: usize, text: bool) -> Option<(usize, usize)> {
    let len = source.len();
    // the user ends at the first colon
    let mut colon = None;
    for (i, &ch) in source.iter().enumerate().skip(start) {
        if ch == ':' {
            colon = Some(i);
            break;
        } else if ch == '/' || ch == '?' || (text && is_text_delimiter(ch)) {
            return None;
        }
    }
    let colon = colon?;
    // the userinfo ends at the last @ before the path or query
    let mut at = None;
    for (i, &ch) in source.iter().enumerate().take(len).skip(colon + 1) {
        if ch == '@' {
            at = Some(i);
        } else if ch == '/' || ch == '?' || (text && is_text_delimiter(ch)) {
            break;
        }
    }
    if at.is_none() {
        // a password with an unencoded / or ? ends at the last @ before a query parameter, the
        // next uri, or (in free text) a whitespace or a quote
        for (i, &ch) in source.iter().enumerate().skip(colon + 1) {
            if ch == '@' {
                at = Some(i);
            } else if ((ch == '?' || ch == '&') && is_query_parameter(source, i + 1))
                || (ch == ':' && starts_with_at(source, "//", i + 1))
                || (text && is_text_delimiter(ch))
            {
                break;
            }
        }
    }
    at.map(|at| (colon + 1, at))
}

/// Whether the text at the given index is a query parameter key followed by `=`.
fn is_query_parameter(source: &[char], from: usize) -> bool {
    for (i, &ch) in source.iter().enumerate().skip(from) {
        if ch == '=' {
            return i > from;
        }
        if matches!(ch, '&' | '?' | '@' | '/' | ':') || ch.is_whitespace() {
            return false;
        }
    }
    false
}

fn is_scheme_char(ch: char) -> bool {
    ch.is_alphanumeric() || ch == '+' || ch == '.' || ch == '-'
}

fn is_text_delimiter(ch: char) -> bool {
    ch.is_whitespace() || ch == '"' || ch == '\''
}

/// Masks the body of PEM private-key blocks within free text, keeping the BEGIN/END markers.
///
/// Public keys and certificates (`BEGIN PUBLIC KEY`, `BEGIN CERTIFICATE`) are left unchanged.
///
/// # Arguments
///
/// * `source` - the text that may contain PEM private-key material
/// * `mask` - the replacement string for the key body (for example `xxxxx`), `None` leaves
///   the source unchanged
///
/// # Returns
///
/// The source with private-key bodies replaced.
pub fn mask_pem_private_key_blocks(source: &str, mask: Option<&str>) -> String {
    let Some(mask) = mask else {
        return source.to_string();
    };
    if source.is_empty() || !contains_ignore_case(source, "-----BEGIN") {
        return source.to_string();
    }
    pem_private_key()
        .replace_all(source, |caps: &regex::Captures| {
            format!("{}{}{}", &caps[1], mask, &caps[3])
        })
        .into_owned()
}

/// Applies value-shape secret masking (URI userinfo passwords and PEM private-key bodies) that
/// cannot be detected by sensitive key names alone.
///
/// See also [`mask_user_info_credentials`] and [`mask_pem_private_key_blocks`].
///
/// # Arguments
///
/// * `source` - the text to mask
/// * `mask` - the replacement string
///
/// # Returns
///
/// The masked text.
pub fn mask_sensitive_value_shapes(source: &str, mask: Option<&str>) -> String {
    let answer = mask_user_info_credentials(source, mask);
    mask_pem_private_key_blocks(&answer, mask)
}

#[cfg(test)]
mod tests {
    use super::*;

    const X: Option<&str> = Some("xxxxx");

    #[test]
    fn test_contains_sensitive() {
        for s in [
            "accessKey",
            "accesstoken",
            "authorizationtoken",
            "clientsecret",
            "passphrase",
            "DB_PASSWORD",
            "app.apiSecret",
            "password",
            "sasljaasconfig",
            "sasl-jaas-config",
            "saslJaasConfig",
            "sastoken",
            "sasToken",
            "sas-token",
            "secret",
            "secretkey",
            "secret-key",
            "secretKey",
            "secret-Key",
            "access-key",
            "access-Key",
            "client-secret",
            "authorization-token",
            "foo.bar.accessKey",
        ] {
            assert!(contains_sensitive(s), "{s}");
        }
        assert!(!contains_sensitive("foo.bar.accessKey."));
        assert!(!contains_sensitive("foo"));
        assert!(!contains_sensitive("bar"));
    }

    #[test]
    fn mask_user_info_credentials_masks_password_in_common_schemes() {
        let cases = [
            (
                "mongodb://user:pass@host:27017/db",
                "mongodb://user:xxxxx@host:27017/db",
            ),
            (
                "mongodb+srv://user:p%40ss@cluster/db",
                "mongodb+srv://user:xxxxx@cluster/db",
            ),
            (
                "amqp://admin:secret@broker:5672/vhost",
                "amqp://admin:xxxxx@broker:5672/vhost",
            ),
            (
                "redis://default:s3cret@redis:6379/0",
                "redis://default:xxxxx@redis:6379/0",
            ),
            (
                "jdbc:mysql://dbuser:dbpass@localhost:3306/app",
                "jdbc:mysql://dbuser:xxxxx@localhost:3306/app",
            ),
            (
                "sftp://USERNAME:PASSWORD@sftp.server.test",
                "sftp://USERNAME:xxxxx@sftp.server.test",
            ),
            (
                "redis://:s3cret@redis:6379/0",
                "redis://:xxxxx@redis:6379/0",
            ),
            (
                "http://user:pass:word@host/path",
                "http://user:xxxxx@host/path",
            ),
        ];
        for (input, expected) in cases {
            assert_eq!(expected, mask_user_info_credentials(input, X));
        }
    }

    #[test]
    fn mask_value_shape_helpers_skip_regex_when_markers_absent() {
        assert_eq!("Hello World", mask_user_info_credentials("Hello World", X));
        assert_eq!(
            "plain log line",
            mask_pem_private_key_blocks("plain log line", X)
        );
        assert_eq!("Hello World", mask_sensitive_value_shapes("Hello World", X));
    }

    #[test]
    fn mask_user_info_credentials_preserves_non_credential_uris() {
        for s in [
            "https://example.com/path",
            "mongodb://user@host:27017/db",
            "mailto:user@example.com",
            "see http://example.com/path:foo for details",
        ] {
            assert_eq!(s, mask_user_info_credentials(s, X));
        }
    }

    #[test]
    fn mask_user_info_credentials_masks_multiple_and_embedded() {
        assert_eq!(
            "primary=mongodb://u1:xxxxx@h1/db secondary=amqp://u2:xxxxx@h2/v",
            mask_user_info_credentials(
                "primary=mongodb://u1:p1@h1/db secondary=amqp://u2:p2@h2/v",
                X
            )
        );
        assert_eq!(
            "{\"url\":\"mongodb://user:xxxxx@host/db\"}",
            mask_user_info_credentials("{\"url\":\"mongodb://user:secret@host/db\"}", X)
        );
    }

    #[test]
    fn mask_user_info_credentials_uses_the_same_rule_as_sanitize_uri() {
        let cases = [
            ("ftp://joe:p@ss@host/in", "ftp://joe:xxxxx@host/in"),
            ("ftp://joe:pa/ss@host/dir", "ftp://joe:xxxxx@host/dir"),
            ("ftp://user@corp.com:pw@host/in", "ftp://user@corp.com:xxxxx@host/in"),
            ("smtp://host:25?to=ops@example.com", "smtp://host:25?to=ops@example.com"),
            (
                "ftp://joe:s3cr3t@ftp.example.com/in?callbackUrl=http://cb.example.com:8080/x&notify=ops@example.com",
                "ftp://joe:xxxxx@ftp.example.com/in?callbackUrl=http://cb.example.com:8080/x&notify=ops@example.com",
            ),
            (
                "Connecting to ftp://joe:pw@host as bob@example.com",
                "Connecting to ftp://joe:xxxxx@host as bob@example.com",
            ),
            ("see http://host:8080/x for bob@example.com", "see http://host:8080/x for bob@example.com"),
        ];
        for (input, expected) in cases {
            assert_eq!(expected, mask_user_info_credentials(input, X), "{input}");
        }
    }

    #[test]
    fn mask_user_info_credentials_handles_empty_and_special_mask() {
        assert_eq!("", mask_user_info_credentials("", X));
        assert_eq!(
            "mongodb://u:p@h/db",
            mask_user_info_credentials("mongodb://u:p@h/db", None)
        );
        assert_eq!(
            "mongodb://u:hide$me@h/db",
            mask_user_info_credentials("mongodb://u:p@h/db", Some("hide$me"))
        );
    }

    #[test]
    fn mask_pem_private_key_blocks_masks_bodies_and_keeps_markers() {
        let rsa = "-----BEGIN RSA PRIVATE KEY-----\nMIIEowIBAAKCAQEA0Z3VS5JJcds3xfn/ygWyF6PZFEw4N8AQ\n-----END RSA PRIVATE KEY-----\n";
        assert_eq!(
            "-----BEGIN RSA PRIVATE KEY-----\nxxxxx\n-----END RSA PRIVATE KEY-----\n",
            mask_pem_private_key_blocks(rsa, X)
        );
        let pkcs8 = "-----BEGIN PRIVATE KEY-----\nMGACAQAwBQYDK2VwBCIEIJ+keyMaterialHere\n-----END PRIVATE KEY-----\n";
        let out = mask_pem_private_key_blocks(pkcs8, X);
        assert!(out.contains("-----BEGIN PRIVATE KEY-----"));
        assert!(out.contains("xxxxx"));
        assert!(out.contains("-----END PRIVATE KEY-----"));
        assert!(!out.contains("keyMaterialHere"));
        let ec = "-----BEGIN EC PRIVATE KEY-----\nMHQCAQEEISecretEcMaterial\n-----END EC PRIVATE KEY-----\n";
        assert!(!mask_pem_private_key_blocks(ec, X).contains("SecretEcMaterial"));
        let enc = "-----BEGIN ENCRYPTED PRIVATE KEY-----\nencrypted-key-material\n-----END ENCRYPTED PRIVATE KEY-----\n";
        let out = mask_pem_private_key_blocks(enc, X);
        assert!(!out.contains("encrypted-key-material"));
        assert!(out.contains("-----BEGIN ENCRYPTED PRIVATE KEY-----"));
        assert!(out.contains("xxxxx"));
    }

    #[test]
    fn mask_pem_private_key_blocks_leaves_public_material_alone() {
        let cert =
            "-----BEGIN CERTIFICATE-----\nMIIDXTCCAkWgAwIBAgIJAKHBj\n-----END CERTIFICATE-----\n";
        assert_eq!(cert, mask_pem_private_key_blocks(cert, X));
        let pubkey = "-----BEGIN PUBLIC KEY-----\nMFwwDQYJKoZIhvcNAQEBBQADSwAwSAJBA\n-----END PUBLIC KEY-----\n";
        assert_eq!(pubkey, mask_pem_private_key_blocks(pubkey, X));
        let lower =
            "-----begin rsa private key-----\nsecretEcMaterial\n-----end rsa private key-----\n";
        assert!(!mask_pem_private_key_blocks(lower, X).contains("secretEcMaterial"));
    }

    #[test]
    fn mask_sensitive_value_shapes_combines_user_info_and_pem() {
        let source = "uri=mongodb://user:pass@host/db\n-----BEGIN PRIVATE KEY-----\nsecret-key-bytes\n-----END PRIVATE KEY-----\n";
        let masked = mask_sensitive_value_shapes(source, X);
        assert!(masked.contains("mongodb://user:xxxxx@host/db"));
        assert!(!masked.contains("pass@"));
        assert!(!masked.contains("secret-key-bytes"));
    }

    #[test]
    fn sensitive_pattern_matches_keys() {
        let re = Regex::new(&format!("(?i){}", get_sensitive_pattern())).unwrap();
        assert!(re.is_match("myPassword"));
        assert!(!re.is_match("timeout"));
        assert!(get_sensitive_keys().contains("password"));
    }
}
